head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil51310n";
scwin.uploadCode = undefined;
scwin.upd_attachBinFiles = null;
scwin.upd_attachBinFiles2 = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — bbsList, param.modifyYn, loadTp, uploadCode

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.upd_attachBinFiles = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachBinFiles') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachBinFiles"]');
        scwin.upd_attachBinFiles2 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachBinFiles2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachBinFiles2"]');
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil51310n.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_attachFileNm", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "if_attachFileNm_2", fn: function(){ return ((String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "if_attachFileNm_3", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "c_when_61", fn: function(){ return (!(String(((dma_pageContext.get("bbsList") ?? "")) == null ? '' : ((dma_pageContext.get("bbsList") ?? ""))).length === 0)); } }, { id: "c_when_121", fn: function(){ return ((String(((dma_pageContext.get("bbsList") ?? "")) == null ? '' : ((dma_pageContext.get("bbsList") ?? ""))).length === 0) && (String(((dma_pageContext.get("modifyYn") ?? "")) == null ? '' : ((dma_pageContext.get("modifyYn") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(dma_basicComInfo.get("comNm")) + "(" + String(dma_basicComInfo.get("isurCd")) + ")"; } },
        { childId: "__rb1", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? "") + " / " + String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["corpUsrNm"] ?? ""); } },
        { childId: "ipt_wrtrNm2", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["corpUsrNm"] ?? ""); } },
        { childId: "ipt_regTelNo2", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["telNo"] ?? ""); } },
        { childId: "ipt_wrtrEmail2", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["email"] ?? ""); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        const uploadCode = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.uploadCode ?? ""))(dma_pageContext.get("uploadCode"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.uploadCode ?? ""))(dma_pageContext.get("uploadCode")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.uploadCode ?? ""))(dma_pageContext.get("uploadCode"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.uploadCode ?? ""))(dma_pageContext.get("uploadCode")))));
        const loadTp = (String(((dma_pageContext.get("loadTp") ?? "")) == null ? '' : ((dma_pageContext.get("loadTp") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("loadTp") ?? "")) == null ? '' : ((dma_pageContext.get("loadTp") ?? ""))));
        if (loadTp === '2') {
            await scwin.checkSave();
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil51310n.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 4건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId","corpUsrNm","telNo","email"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil51310n' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_fn_PrelistPageSearch, tx_fn_register) — 어느 것이 «열자마자» 인지 정할 근거가 없다

