/**
 * @method
 * @name tx_fn_PrelistPageSearch
 * @description Prelist Page Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_PrelistPageSearch = async function () {
    const sbmOptions = {
        id: "tx_fn_PrelistPageSearch",
        method: "post",
        action: "/listInvstg/listPrelmInvstg.do",
        ref: "dma_PrelistPageSearchReq",
        target: "dlt_bbsList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
