///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkSave
 * @description check Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSave = async function () {
    const uploadCode = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.uploadCode ?? ""))(dma_pageContext.get("uploadCode"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.uploadCode ?? ""))(dma_pageContext.get("uploadCode")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.uploadCode ?? ""))(dma_pageContext.get("uploadCode"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (scwin.uploadCode ?? ""))(dma_pageContext.get("uploadCode")))));
    if (uploadCode === '0') {
        await $c.win.alert('저장되었습니다.');
    } else {
        if (uploadCode === '1') {
            await $c.win.alert('해당유형의 파일은 업로드할 수 없습니다.');
        } else {
            if (uploadCode === '2') {
                await $c.win.alert('업로드 하려는 파일의 크기가 허용한도를 초과 하였습니다.');
            } else {
                await $c.win.alert('저장시 오류가 발생하였습니다.');
            }
        }
    }
};

/**
 * @method
 * @name prelistPageSearch
 * @description prelist Page Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.prelistPageSearch = async function () {
    const frm = (document.preListForm || { elements: [] });
    const gongmo = $c.util.getComponent('dma_PrelistPageSearchReq').get('gongMo');
    frm.action = 'listPrelmInvstg.do';
    $c.util.getComponent('dma_PrelistPageSearchReq').set('method', "listPrelmInvstgList");
    if (gongmo === "Y") {
        $c.util.getComponent('dma_PrelistPageSearchReq').set('page', "konexGongsamo");
    } else {
        $c.util.getComponent('dma_PrelistPageSearchReq').set('page', "konex");
    }
    await scwin.tx_fn_PrelistPageSearch();
};

/**
 * @method
