 */
scwin.goList = async function () {
    $c.util.getComponent('dma_PrelistPageSearchReq').set('method', 'searchCommentLetterList');
    $c.util.getComponent('dma_PrelistPageSearchReq').set('page', '30');
    const nr = await scwin.tx_fn_goList('bbs.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil51300/jldfil51300.xml", { "method": 'searchCommentLetterList', "page": '30' });
    }
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (await scwin.nullChk($c.util.getComponent("ipt_wrtrNm"))) {
        return;
    }
    if (await scwin.nullChk($c.util.getComponent("ipt_regTelNo"))) {
        return;
    }
    if (await scwin.nullChk($c.util.getComponent("ipt_wrtrEmail"))) {
        return;
    }
    if (await scwin.nullChk($c.util.getComponent("ipt_contnTitle"))) {
        return;
    }
    if (await scwin.nullChk($c.util.getComponent("txa_contnContn"))) {
        return;
    }
    $c.util.getComponent('dma_PrelistPageSearchReq').set('method', 'registCommentLetter');
    $c.util.getComponent('dma_PrelistPageSearchReq').set('modifyYn', '' + dma_pageContext.get("modifyYn") + '');
    $c.util.getComponent('dma_PrelistPageSearchReq').set('replyYn', '' + dma_pageContext.get("replyYn") + '');
    $c.util.getComponent('dma_PrelistPageSearchReq').set('contnId', '' + dma_pageContext.get("contnId") + '');
    $c.util.getComponent('dma_PrelistPageSearchReq').set('contnAttachSeq', '' + dma_pageContext.get("contnAttachSeq") + '');
    await scwin.tx_fn_register('bbs.do');
};

/**
 * @method
 * @name isNull
 * @description is Null 처리
 * @param {*} _obj _obj
 * @param {*} _msg _msg
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isNull = async function (_obj, _msg) {
    if ($c.str.trim(_obj.value) === '' || _obj.value == null) {
        await $c.win.alert("'" + _msg + "' 항목을 입력하세요.");
        _obj.focus();
        return true;
    }
    return false;
};

/**
 * @method
 * @name nullChk
 * @description null Chk 처리
 * @param {*} _obj _obj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.nullChk = async function (_obj) {
    return await scwin.isNull(_obj, ((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj));
};

/**
 * @method
 * @name checkByte
 * @description check Byte 처리
 * @param {*} _obj _obj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkByte = async function (_obj) {
    const standardByte = 2000;
    const contnByte = scwin.getByte(_obj);
    const byteCntObj = $c.util.getComponent("txt_byteCnt");
    byteCntObj.innerText = "질의내용\n(" + (contnByte) + "/2000 byte)";
    if (contnByte > standardByte) {
        await $c.win.alert((contnByte - standardByte) + "바이트가 초과되었습니다. 초과된 내용은 자동삭제됩니다.\n");
        const contnValue = _obj.getValue();
        _obj.setValue(scwin.calcContn(contnValue, standardByte));
        await scwin.checkByte(_obj);
    }
};

/**
 * @method
 * @name getByte
 * @description get Byte 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.getByte = function (_obj) {
    const sTmpCntnt = new String(_obj.getValue());
    let iCounts = 0;
    for (let i = 0; i < sTmpCntnt.length; i++) {
        const escapeChar = escape(sTmpCntnt.charAt(i));
        if (escapeChar === '%0A') {
            iCounts += 2;
        } else {
            if (escapeChar.length > 4) {
                iCounts += 2;
            } else {
                iCounts++;
            }
        }
    }
    return iCounts;
};

/**
 * @method
 * @name calcContn
 * @description calc Contn 처리
 * @param {*} _contn _contn
 * @param {*} _maximum _maximum
 * @returns {void}
 * @hidden N
 */
scwin.calcContn = function (_contn, _maximum) {
    let rContn = "";
    let nbytes = 0;
    for (let i = 0; i < _contn.length; i++) {
        const ch = _contn.charAt(i);
        let inc = 0;
        if (escape(ch) === '%0A') {
            inc = 2;
        } else {
            if (escape(ch).length > 4) {
                inc = 2;
            } else {
                inc = 1;
            }
        }
        nbytes += inc;
        if (nbytes > _maximum) {
            break;
        }
        rContn += ch;
    }
    return rContn;
};

/**
 * @method
 * @name deleteAttachFile
 * @description delete Attach File 처리
 * @param {String} contnId contnId
 * @param {*} contnAttachSeq contnAttachSeq
