    const pafObj = $c.util.getComponent("presentAttachFile");
    pafObj.innerText = "현재 등록된 파일 : 없음.";
    const fileUpObj = $c.util.getComponent("fileUpBtn");
    (($c.util.getComponent("fileUpBtn")) && ($c.util.getComponent("fileUpBtn")).setValue ? ($c.util.getComponent("fileUpBtn")).setValue("<input type='file' name='attachBinFiles' id='attachBinFiles' title='파일' style='width:500;'/>") : (($c.util.getComponent("fileUpBtn")) ? (($c.util.getComponent("fileUpBtn")).innerHTML = "<input type='file' name='attachBinFiles' id='attachBinFiles' title='파일' style='width:500;'/>") : void ("<input type='file' name='attachBinFiles' id='attachBinFiles' title='파일' style='width:500;'/>")));
};
